#include <bits/stdc++.h>
using namespace std;

void solve(){
    int n;cin>>n;
    vector<pair<int,int>> a(n);
    map<int,int> mp1,mp2;
    
    for(int i=0;i<n;i++){
        cin>>a[i].first>>a[i].second;
        mp1[a[i].first]++; mp2[a[i].second]++;
        if (mp1[a[i].first]>=3 or mp2[a[i].second]>=3){
            cout<<"NO"<<"\n";  return;
        }
    }
    
    sort(a.begin(), a.end());
    
    int x1=a[0].first, y1=a[0].second;
    
    int flag=0; //pattern 0
    
    int ans1=1; //yes
  
    for(int i=1;i<n;i++){
        int x=a[i].first;
        int y=a[i].second;
        
        if(y<=y1){
            if(flag==1){
                    ans1=0; break;
                }
        flag=1;
        
    }
    x1=x; y1=y;
}


//check ans2


for(int i=0;i<n;i++){
    int x=a[i].first;
    int y=a[i].second;
    
    a[i].first=y;
    a[i].second=x;
    
}

int ans2=1; //yes

sort(a.begin(), a.end());
x1=a[0].second;y1=a[0].first;

flag=0;

for(int i=1;i<n;i++){
    int x=a[i].second;
    int y=a[i].first;
    if(x<=x1){
        if(flag==1){
            ans2=0; break;
        }
        flag=1;
    }
    x1=x;y1=y;
}

//cout<<ans1<<" "<<ans2<<"\n";
if(ans1 || ans2) cout<<"YES"<<"\n";
else{cout<<"NO"<<"\n";}

}


int main() {
	int t;cin>>t;
	while(t--){
	    solve();
	}

}
